package finance.data.serializer;

import finance.fund.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

public final class FundDataSerializer {
    private FundDataSerializer(){}
    public static void save(CompoundTag root){
        ListTag funds=new ListTag();FundManager.definitions().forEach((id,d)->{FundState s=FundManager.states().get(id);if(s==null)return;CompoundTag t=new CompoundTag();t.putString("Id",id);t.putString("Name",d.displayName());t.putString("Type",d.type().name());t.putString("Rule",d.selectionRule());t.putInt("Mgmt",d.managementFeeBps());t.putInt("SubFee",d.subscriptionFeeBps());t.putInt("RedFee",d.redemptionFeeBps());t.putLong("Min",d.minimumSubscription());t.putInt("Rebalance",d.rebalanceIntervalDays());t.putInt("MaxWeight",d.maxConstituentWeightBps());t.putString("Status",s.status().name());t.putLong("Shares",s.totalShareUnits());t.putLong("Nav",s.currentNav());t.putLong("PrevNav",s.previousNav());t.putLong("NavDay",s.lastNavDay());t.putLong("FeeDay",s.lastFeeDay());t.putLong("Fees",s.accruedFees());t.putLong("Income",s.realizedIncome());t.putInt("ConstituentVersion",s.constituentVersion());t.putLong("EffectiveDay",s.constituentEffectiveDay());t.putLong("RebalanceDay",s.lastRebalanceDay());t.putString("Reason",s.suspensionReason());ListTag history=new ListTag();for(FundNavPoint p:s.navHistory()){CompoundTag n=new CompoundTag();n.putLong("Day",p.mcDay());n.putLong("Nav",p.nav());n.putLong("Assets",p.netAssets());n.putLong("Shares",p.totalShareUnits());n.putLong("Benchmark",p.benchmarkLevel());n.putBoolean("Degraded",p.degradedPrice());history.add(n);}t.put("History",history);funds.add(t);});root.put("Funds",funds);
        ListTag positions=new ListTag();FundManager.positions().forEach((player,map)->map.forEach((id,p)->{CompoundTag t=new CompoundTag();t.putUUID("Player",player);t.putString("Fund",id);t.putLong("Shares",p.shareUnits());t.putLong("Frozen",p.frozenShareUnits());t.putLong("Cost",p.totalCost());t.putLong("Realized",p.realizedProfit());positions.add(t);}));root.put("FundPositions",positions);
        ListTag requests=new ListTag();for(FundRedemptionRequest r:FundManager.requests().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",r.id());t.putUUID("Player",r.playerId());t.putString("Fund",r.fundId());t.putLong("Shares",r.shareUnits());t.putLong("Day",r.createdDay());t.putString("Status",r.status().name());t.putString("Reason",r.failureReason());t.putLong("Paid",r.paidAmount());requests.add(t);}root.put("FundRedemptions",requests);
        ListTag plans=new ListTag();for(FundInvestmentPlan p:FundManager.plans().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",p.id());t.putUUID("Player",p.playerId());t.putString("Fund",p.fundId());t.putLong("Amount",p.amount());t.putInt("Interval",p.intervalDays());t.putLong("Next",p.nextExecutionDay());t.putLong("Last",p.lastAttemptDay());t.putInt("Failures",p.failureCount());t.putString("Status",p.status().name());plans.add(t);}root.put("FundPlans",plans);
        ListTag keys=new ListTag();for(String key:FundManager.operationKeys()){CompoundTag t=new CompoundTag();t.putString("Key",key);keys.add(t);}root.put("FundOperationKeys",keys);
        ListTag acknowledgements=new ListTag();for(String key:FundManager.riskAcknowledgements()){CompoundTag t=new CompoundTag();t.putString("Key",key);acknowledgements.add(t);}root.put("FundRiskAcknowledgements",acknowledgements);
    }
    public static void load(CompoundTag root){FundManager.clearDirect();
        for(Tag raw:root.getList("Funds",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;FundDefinition d=new FundDefinition(t.getString("Id"),t.getString("Name"),FundType.valueOf(t.getString("Type")),t.getString("Rule"),t.getInt("Mgmt"),t.getInt("SubFee"),t.getInt("RedFee"),t.getLong("Min"),t.getInt("Rebalance"),t.getInt("MaxWeight"));long shares=t.getLong("Shares"),nav=t.getLong("Nav"),prev=t.getLong("PrevNav");if(shares<0||nav<=0||prev<=0)continue;List<FundNavPoint> history=new ArrayList<>();for(Tag nraw:t.getList("History",Tag.TAG_COMPOUND)){CompoundTag n=(CompoundTag)nraw;long day=n.getLong("Day"),nnav=n.getLong("Nav"),assets=n.getLong("Assets"),units=n.getLong("Shares");if(day>=0&&nnav>0&&assets>=0&&units>=0)history.add(new FundNavPoint(day,nnav,assets,units,n.getLong("Benchmark"),n.getBoolean("Degraded")));}FundState s=new FundState();s.restore(FundStatus.valueOf(t.getString("Status")),shares,nav,prev,t.getLong("NavDay"),t.getLong("FeeDay"),Math.max(0,t.getLong("Fees")),Math.max(0,t.getLong("Income")),Math.max(0,t.getInt("ConstituentVersion")),t.getLong("EffectiveDay"),t.getLong("RebalanceDay"),t.getString("Reason"),history);FundManager.registerDirect(d,s);}catch(Exception ignored){}}
        for(Tag raw:root.getList("FundPositions",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;UUID player=t.getUUID("Player");String id=FundDefinition.normalize(t.getString("Fund"));long shares=t.getLong("Shares"),frozen=t.getLong("Frozen"),cost=t.getLong("Cost");if(FundManager.definitions().containsKey(id)&&shares>0&&frozen>=0&&frozen<=shares&&cost>=0){PlayerFundPosition p=new PlayerFundPosition();p.restore(shares,frozen,cost,t.getLong("Realized"));FundManager.putPositionDirect(player,id,p);}}catch(Exception ignored){}}
        for(Tag raw:root.getList("FundRedemptions",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;FundRedemptionRequest r=new FundRedemptionRequest(t.getUUID("Id"),t.getUUID("Player"),t.getString("Fund"),t.getLong("Shares"),t.getLong("Day"),FundRedemptionRequest.Status.valueOf(t.getString("Status")));if(r.shareUnits()<=0||r.createdDay()<0||!FundManager.definitions().containsKey(r.fundId()))continue;r.restore(r.status(),t.getString("Reason"),t.getLong("Paid"));FundManager.putRequestDirect(r);}catch(Exception ignored){}}
        for(Tag raw:root.getList("FundPlans",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;FundInvestmentPlan p=new FundInvestmentPlan(t.getUUID("Id"),t.getUUID("Player"),t.getString("Fund"),t.getLong("Amount"),t.getInt("Interval"),t.getLong("Next"),FundInvestmentPlan.Status.valueOf(t.getString("Status")));if(p.amount()<=0||p.intervalDays()<=0||p.nextExecutionDay()<0||!FundManager.definitions().containsKey(p.fundId()))continue;p.restore(t.getLong("Last"),t.getInt("Failures"));FundManager.putPlanDirect(p);}catch(Exception ignored){}}
        for(Tag raw:root.getList("FundOperationKeys",Tag.TAG_COMPOUND)){String key=((CompoundTag)raw).getString("Key");FundManager.addOperationKeyDirect(key);}
        for(Tag raw:root.getList("FundRiskAcknowledgements",Tag.TAG_COMPOUND)){String key=((CompoundTag)raw).getString("Key");FundManager.addRiskAcknowledgementDirect(key);}
        if(FundManager.definitions().isEmpty())FundManager.seedDefaultsIfNeeded();
    }
}
